import type { Register } from 'claude-code'

// The engine's last suggestion that actually showed, until a new turn makes it stale.
let pending: string | undefined

// Commands that move the conversation somewhere the old suggestion no longer
// fits. /clear and /resume need no entry: they end the session (below).
const staleAfter = new Set(['rewind'])

export const register: Register = on => {
  on('prompt.suggest', async ($, e, next) => {
    const shown = await next(e)
    if (e.origin.kind === 'suggestion' && shown.isShown) pending = e.text
    return shown
  })

  // A model turn (a plain prompt, or a slash command that prompts the model)
  // will produce a fresh suggestion of its own, so the old one is done.
  on('turn.start', ($, e, next) => {
    pending = undefined
    return next(e)
  })

  // /clear, /resume and /logout end the session; its suggestion goes with it.
  on('session.end', ($, e, next) => {
    pending = undefined
    return next(e)
  })

  on('command.run', async ($, e, next) => {
    if (staleAfter.has(e.command)) pending = undefined
    const text = pending
    const ran = await next(e)
    if (text === undefined || pending !== text) return ran

    // Core won't show a suggestion while the command is still running, and it
    // counts as running until this hook returns. So re-propose from a timer,
    // retrying a few times; suggest() itself waits out a dialog (/copy's picker).
    const delays = [0, 50, 200, 500, 1000]
    const attempt = (i: number) => {
      const delay = delays[i]
      if (delay === undefined) return
      $.clock.after(delay, async () => {
        if (pending !== text) return
        const { isShown } = await $.prompt.suggest({ text })
        if (!isShown) attempt(i + 1)
      })
    }
    attempt(0)
    return ran
  })
}

